using System.Collections.Generic;
using UnityEngine;
namespace Blocklands {
 public partial class RegionActivities:MonoBehaviour {
  Sandbox game;RoyalArt art;int region;readonly List<Transform> markers=new List<Transform>();readonly HashSet<int> found=new HashSet<int>();readonly int[] rune={0,0,0};readonly int[] answer={1,2,0};bool running,won,paid;float remaining;Vector3 board;Font font;
  public string Title=>region==0?"小禾的萤火野餐":region==3?"梦影三符文宝库":"熔岩冷却踏石";
  public Vector3 StartPoint=>board;public bool Running=>running;public bool Won=>won;public Vector3 Marker(int i)=>markers[i].position;public int Count=>markers.Count;
  public void Initialize(Sandbox g){game=g;region=g.World.Region;font=Resources.Load<Font>("NotoSansCJKsc-Regular");art=gameObject.AddComponent<RoyalArt>();
   board=Ground(region==0?new Vector3(24,0,25):new Vector3(30,0,12));
   art.Piece("活动告示牌立柱",board+Vector3.up,new Vector3(.18f,2,.18f),new Color(.45f,.27f,.13f));art.Piece("活动告示牌",board+Vector3.up*1.8f,new Vector3(2.6f,.9f,.16f),new Color(.22f,.35f,.3f));
   var label=new GameObject("活动名称").AddComponent<TextMesh>();label.transform.SetParent(transform,false);label.transform.position=board+new Vector3(0,1.85f,-.1f);label.font=font;label.GetComponent<Renderer>().sharedMaterial=font.material;label.text=Title+"\n靠近按 G";label.characterSize=.1f;label.fontSize=32;label.anchor=TextAnchor.MiddleCenter;label.color=Color.white;
   if(region==0){BuildCompactFireflies();}
   else if(region==3){for(int i=0;i<3;i++){Vector3 p=Ground(board+new Vector3((i-1)*3,0,5));art.Piece("符文石柱",p+Vector3.up*.65f,new Vector3(.9f,1.3f,.9f),new Color(.3f,.2f,.45f));AddMarker(p+Vector3.up*1.6f,Color.yellow,"符文 "+(i+1));}}
   else {for(int i=0;i<6;i++){Vector3 p=Ground(new Vector3(25+(i%2)*2.6f,0,16+i*3.6f));p.y=Mathf.Max(11.3f,p.y+.3f);art.Piece("冷却踏石 "+(i+1),p-Vector3.up*.25f,new Vector3(2.2f,.5f,2.2f),new Color(.2f,.55f,.64f),PrimitiveType.Cube,true);AddMarker(p+Vector3.up*.8f,new Color(.4f,1,1),"冷却火种 "+(i+1));}}
  }
  Vector3 Ground(Vector3 p){int x=Mathf.Clamp(Mathf.RoundToInt(p.x),2,61),z=Mathf.Clamp(Mathf.RoundToInt(p.z),2,61);for(int y=30;y>=0;y--){Block b=game.World.Get(new Vector3Int(x,y,z));if(b!=Block.Air&&b!=Block.Leaves&&b!=Block.Wood)return new Vector3(x+.5f,y+1,z+.5f);}return new Vector3(x+.5f,11,z+.5f);}
  void AddMarker(Vector3 p,Color color,string name){var m=art.Piece(name,p,Vector3.one*.42f,color,PrimitiveType.Sphere);markers.Add(m);var halo=art.Piece("光环",p,new Vector3(.75f,.05f,.75f),color,PrimitiveType.Cylinder);halo.SetParent(m,true);}
  public bool Interact(){if(!game.FestivalInputAvailable||game.FestivalLocked)return false;Vector3 p=game.Player.transform.position;if(!running&&Vector3.Distance(p,board)<4){running=true;won=false;remaining=region==0?120:region==5?45:0;found.Clear();for(int i=0;i<3;i++)rune[i]=0;foreach(var m in markers){m.gameObject.SetActive(true);if(region==3)m.GetComponent<Renderer>().material.color=Color.yellow;}game.Notice=region==0?"120秒内收集8只萤火虫，靠近光点即可。":region==3?"石碑提示：月亮→星星→太阳。靠近每根柱子按G切换图案。":"45秒内依次落在6块踏石上，跳跃有效，飞行不计数。";return true;}
   if(running&&region==3){int nearest=0;for(int k=1;k<3;k++)if(Vector3.Distance(p+Vector3.up,markers[k].position)<Vector3.Distance(p+Vector3.up,markers[nearest].position))nearest=k;for(int i=nearest;i<=nearest;i++)if(Vector3.Distance(p+Vector3.up,markers[i].position)<2.5f){rune[i]=(rune[i]+1)%3;markers[i].GetComponent<Renderer>().material.color=rune[i]==0?Color.yellow:rune[i]==1?Color.cyan:new Color(.8f,.4f,1);game.Notice="第"+(i+1)+"符文："+Symbol(rune[i]);if(rune[0]==answer[0]&&rune[1]==answer[1]&&rune[2]==answer[2])Complete();return true;}}return false;}
  static string Symbol(int i)=>i==0?"太阳":i==1?"月亮":"星星";
  public void Tick(float dt){if(!running||game.Paused)return;if(region!=3){remaining-=dt;if(remaining<=0){running=false;game.Notice="时间到了，回告示牌按G再试一次。";return;}for(int i=0;i<markers.Count;i++){if(found.Contains(i)||region==5&&(i!=found.Count||game.Player.Flying))continue;var delta=game.Player.transform.position+Vector3.up*.8f-markers[i].position;if(delta.magnitude<(region==5?1.25f:1.8f)){found.Add(i);markers[i].gameObject.SetActive(false);game.Notice=(region==0?"萤火虫 ":"踏石 ")+found.Count+" / "+markers.Count;if(found.Count==markers.Count){Complete();break;}}}}}
  void Complete(){bool firstReward=!paid;running=false;won=true;foreach(var m in markers)m.gameObject.SetActive(false);Block reward=region==0?Block.Cookie:region==3?Block.ShadowCrystal:Block.Iron;int goods=region==0?6:region==3?3:8,goodsBefore=game.Inventory[(int)reward];if(firstReward){paid=true;game.Inventory[(int)reward]=Mathf.Min(9999,goodsBefore+goods);}int earned=game.EarnActivityCoins(30,Title);if(earned==0&&firstReward){game.Inventory[(int)reward]=goodsBefore;paid=false;}if(earned>0)game.Notice=Title+"完成，获得"+earned+"元"+(firstReward?"和地区物品。":"；再玩还能获得奖励。");if(transform.Find("完成宝箱")!=null)return;var prize=art.Piece("完成宝箱",board+new Vector3(2,.4f,0),new Vector3(1,.8f,.7f),new Color(.95f,.68f,.3f));if(region==0){art.Piece("野餐垫",Ground(board+new Vector3(0,0,2))+Vector3.up*.03f,new Vector3(3,.04f,2),new Color(.97f,.5f,.67f));var friend=RoyalArt.Girl(transform,true,false);friend.transform.position=Ground(board+new Vector3(2,0,2));}}
  void Update(){if(game==null)return;Tick(Time.deltaTime);if(!game.Paused)foreach(var m in markers)if(m.gameObject.activeSelf)m.Rotate(0,Time.deltaTime*45,0);}
  void OnGUI(){if(game==null||game.Paused||game.PhoneOpen||game.PalaceConsoleOpen)return;bool near=Vector3.Distance(game.Player.transform.position,board)<16;if(!near&&!running)return;var old=GUI.skin.font;GUI.skin.font=font;GUI.Box(new Rect(18,180,420,105),"");var style=new GUIStyle(GUI.skin.label){fontSize=17,wordWrap=true};style.normal.textColor=Color.white;string text=Title+"\n";if(running)text+=region==3?"目标：月亮 → 星星 → 太阳\n当前："+Symbol(rune[0])+" / "+Symbol(rune[1])+" / "+Symbol(rune[2])+" · 靠近柱子按G":Mathf.CeilToInt(remaining)+"秒 · "+found.Count+" / "+markers.Count+"\n"+(region==5?"按顺序跳上青色踏石，飞行不计数。":"收集周围的金色光点。");else text+=(won?"已完成，可回告示牌重玩。":"靠近绿色告示牌，按 G 开始。")+"\n告示牌距离："+Mathf.RoundToInt(Vector3.Distance(game.Player.transform.position,board))+"米";GUI.Label(new Rect(30,186,395,95),text,style);DrawFireflyHints();GUI.skin.font=old;}
 }
 public partial class Sandbox {
  public RegionActivities Activity {get;private set;}
  void RefreshActivities(){if(Activity!=null){Activity.gameObject.SetActive(false);Destroy(Activity.gameObject);}Activity=null;if(World.Region!=0&&World.Region!=3&&World.Region!=5)return;var root=new GameObject("地区游玩活动");Activity=root.AddComponent<RegionActivities>();Activity.Initialize(this);}
 }
}
